async function submitReport(reportData: any) {
  try {
    const response = await client.v2_hunter_reports({ body: reportData });
    console.log("Report submitted successfully:", response);
    return response;
  } catch (error) {
    console.error("Failed to submit report:", error);
    return null;
  }
}
```

